        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin input_602_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_toList()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil54200.input_602_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_register = async function () {
    const sbmOptions = {
        id: "tx_fn_register",
        method: "post",
        action: "/listInvstg/cap.do",
        ref: "dma_registerReq",
        target: "dlt_acntgBasCd=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil54200.tx_fn_register" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.register = async function () {
    /* sdd-asis-lifecycle:begin fn_register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = $c.util.getComponent('CapForm');
    if ($c.util.getComponent('dma_registerReq').get('fncWrtTpCd')=== '1') {
        $c.util.getComponent('dma_registerReq').set('fncWrtTpCd', '2');
        $c.util.getComponent('dma_registerReq').set('method', 'insertCap');
    } else {
        if ($c.util.getComponent('dma_registerReq').get('fncWrtTpCd')=== '2') {
            $c.util.getComponent('dma_registerReq').set('method', 'updateCap');
        }
    }
    frm.action = 'cap.do';
    await scwin.tx_fn_register();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setSelectBox
 * @author Inswave
 * @date 2026. 09. 29
 * @param listBzSeq
 * @returns
 * @hidden N
*/
scwin.setSelectBox = function (listBzSeq) {
    /* sdd-asis-lifecycle:begin setSelectBox — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const date = new Date();
    let year = "";
    const month = "";
    document.write("<option value='0000'>--- 선택 ---</option>");
    switch (listBzSeq) {
        case 1:
        for (var i = 6; i > 0; i--) {
            year = date.getFullYear();
            var text = "";
            if ($c.util.getComponent('slc_acntclsYy').getValue() === year) {
                text = "selected";
            }
            document.write("<option value='" + year + "' " + text + ">" + year + "년</option>");
            date.setYear(date.getFullYear() - 1);
        }
        break;
        case 2:
        for (var i = 6; i > 0; i--) {
            year = date.getFullYear();
            var text = "";
            if ($c.util.getComponent('slc_acntclsYy').getValue() === year) {
                text = "selected";
            }
            document.write("<option value='" + year + "' " + text + ">" + year + "년</option>");
            date.setYear(date.getFullYear() - 1);
        }
        break;
        case 3:
        for (var i = 6; i > 0; i--) {
            year = date.getFullYear();
            var text = "";
            if ($c.util.getComponent('slc_acntclsYy').getValue() === year) {
                text = "selected";
            }
            document.write("<option value='" + year + "' " + text + ">" + year + "년</option>");
            date.setYear(date.getFullYear() - 1);
        }
        break;
        case 4:
        for (var i = 6; i > 0; i--) {
            year = date.getFullYear();
            var text = "";
            if ($c.util.getComponent('slc_acntclsYy').getValue() === year) {
                text = "selected";
            }
            document.write("<option value='" + year + "' " + text + ">" + year + "년</option>");
            date.setYear(date.getFullYear() - 1);
        }
        break;
    }
    /* sdd-asis-lifecycle:end */
};
